"""Freeze the one-change compiled reverse-verifier experiment before execution."""
from common import ROOT,SRC,OUT,BASE,sha,read,save,now

def main():
    assert not(SRC/'protocol.json').exists()and not(OUT/'compilation-gate.json').exists();OUT.mkdir(parents=True,exist_ok=True)
    p=read(SRC.parent/'h3af/protocol.json')
    p.update(id='H3ag-compiled-literal-reverse-verifier-N15',frozen_utc=now(),hypothesis='For both unchanged N12 learned positive-F recipes extended to N15, a complete CPU compile, independently verified by a compiled literal reverse enumerator, plus the external graph gate, cache loading and three 4096-input queries is at least 10 times faster than three frozen GPU permutation solve calls. Full C++ build and equivalence validation cost is conservatively charged to each family.',interpretation='One algorithm-implementation change relative to failed H3af: the same independent reverse-row literal-F recursion is translated to single-thread C++. Forward Python enumeration, dense all-cell-pair certificate formula, source models, GPU kernels and inherited caps are unchanged. A new experiment, not an extension of H3af. Fixed-cap heterogeneous CPU/GPU timing, not newly matched N15 time.')
    p['eligibility']='q=15; positive J exactly on binary symmetric F with zero diagonal, zero h, complete row and column cliques. Thus cardinality-15 zero-F states are exactly row/column permutations. Full forward and independent compiled reverse enumeration must agree exactly.'
    p['compilation'].update(primary='Unchanged H3af Python forward-row future-row F-mask recursion.',independent='Single-thread C++ translation of H3af reverse_literal: rows q-1 down to 0, columns 0 through q-1, literal F[cell,old] against each selected cell; sort all complete columns. No forward masks, supplied graph or special leaper rules.',gate='Fresh 120 aggregate CPU-second gate includes monitor and child processes, C++ build, all parity/query verification, source transfer, both N15 enumerations, unchanged dense all-cell-pair certificates, index and cache serialization. Live /proc process-tree CPU monitoring plus final self+children rusage; conservative 120 wall-second guard. Failure stops entire study without partial substitution, extension or dropped family.',cache='Both complete caches must be sealed before external geometry or target cohorts. Rerun from frozen source models; H3af provisional outputs and completed N15 cache are never inputs.')
    p['compiled_verifier']=dict(compiler_version='g++ (Ubuntu 13.3.0-6ubuntu2~24.04.1) 13.3.0',flags=['-O3','-std=c++17','-DNDEBUG','-Wall','-Wextra','-Werror'],threads=1,input='q plus dense uint8 F; no forward masks or geometry',output='all sorted uint8 columns',validation=dict(seed=2026113101,q=list(range(2,8)),densities=[0,.1,.5,.9,1],edge_cases='Add one off-clique edge to row/column cliques, remove one off-clique edge from full graph. Preserve row/column cliques in every fixture.',small_reference='Require full array equality among original Python reverse, compiled reverse, original forward and exhaustive itertools.permutations with literal pair tests.',prior_N13='Recompute both complete H3ad N13 model-only solution arrays with all three enumerators and compare to prior sealed H3ae arrays. Prior caches used only as validation references, never N15 compiler inputs.',synthetic_query='Rerun clue-only query gate inside shared prerequisite timer.'),cost='Build and all prerequisite verification, monitor/import overhead charged once to aggregate CPU gate and full shared wall cost charged to EACH family CPU speed denominator. Preserve binary SHA and compiler version. Dense certificate time separately recorded without changing its formula.')
    p['query']['random_seed']='numpy default_rng(2026113100+100*family_index+searchseed)'
    p['target']['input_seeds']=[2026112523,2026112524]
    p['target']['exclusion']='H3af produced no N15 cohort. Reserve family0 then family1; exclude first new family keys from second. Uniform over remaining eligible keys. N13 key domain is distinct.'
    p['timing'].update(cpu_denominator='Full shared build/equivalence/query-validation/monitor overhead charged separately to EACH family, plus its source transfer/N13 identity checks, eligibility, forward and compiled reverse enumerations, unchanged dense pair verification, indexing/serialization, external graph gate, cache load and three query calls. Failed costs retained. Cohort preparation/shared starts and target scoring are reported separately.',scheduling='Compilation prerequisites and both complete N15 caches before external graph gate/cohorts/GPU work. Unchanged GPU kernels, same inherited source units and caps. Query worker may overlap GPU controls; no other Loki experiment concurrently.',comparison='GPU three synchronized solve-call wall times divided by full shared prerequisite wall cost plus per-family compile, external graph gate, load and three queries. Conservative double charge of shared build/validation across family denominators, actual aggregate costs reported once. No repeated-compilation confidence interval.')
    p['budget']['compilation_wall_seconds_guard']=120
    p['budget']['enforcement']='120 aggregate CPU seconds including subprocess compiler/build/parity and monitor, additionally 120 wall-second guard. Stop signal at119.8 allows receipt shutdown; final pass requires both totals<=120. After complete compilation and external gate/cohorts, unchanged 600 aggregate GPU-worker seconds, 300 cumulative per GPU and360 GPU-phase wall seconds; all warmups/scoring/serialization included. No reset/extension/partial cache.'
    p['limits'].append('Compiled verifier optimization includes full build and equivalence-validation cost in each family denominator; this tests an implementation bottleneck, not a changed model or general N15 solver claim.')
    sources=[SRC/f'{name}.py' for name in ['common','transfer','compiler','compile_gate','cpp_verifier','graph_gate','query','validate_query','prepare','driver','campaign','freeze']]+[SRC/'reverse_literal.cpp']+[SRC.parent/f'h3aa/{name}.py' for name in ['initialization','arbitrary_backend','permutation_backend']]+[SRC.parent/f'{study}/{name}' for study,name in [('h3af','protocol.json'),('h3af','compiler.py'),('h3ae','protocol.json'),('h3ae','compiler.py'),('h3ad','protocol.json')]]
    data=[ROOT/m[key] for m in p['models'] for key in ['parameters_path','source_design_path','inherited_n13_model_path','calibration_selection_path']]+[BASE/f'h3ae/b{b}/cache.npz' for b in range(2)]
    p.update(source_sha256={str(x.relative_to(ROOT)):sha(x) for x in sources},source_data_sha256={str(x.relative_to(ROOT)):sha(x) for x in data},target_data_sha256={str((BASE/'h3ae/campaign.json').relative_to(ROOT)):sha(BASE/'h3ae/campaign.json')})
    save(SRC/'protocol.json',p);print('FROZEN',sha(SRC/'protocol.json'),flush=True)
if __name__=='__main__':main()
